package com.chubb.apac.claims.modulith.assessment.mapper;import com.chubb.apac.claims.modulith.assessment.model.*;import java.util.List;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class AssessmentMapperTest{@Test void maps(){Assessment a=new Assessment();a.setAssessmentId("ASM-1");a.setClaimId("CLM-1");a.setAssessorId("S1");a.setMarket(com.chubb.apac.claims.modulith.common.enums.Market.SG);a.setProductType(com.chubb.apac.claims.modulith.common.enums.ProductType.MOTOR);a.setFindings("F");a.setRecommendedDecision(RecommendedDecision.APPROVE);a.setRecommendationReason("R");a.setRiskFactors(List.of());a.setStatus(AssessmentStatus.SUBMITTED);assertThat(new AssessmentMapper().toResponse(a).assessmentId()).isEqualTo("ASM-1");}}
